export default {async fetch(req,env,ctx){const url=new URL(req.url);if(!url.pathname.startsWith('/api/')&&url.pathname!='/health'){return new Response(INDEX_HTML,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store'}})}try{return await handle(req,env,ctx)}catch(e){console.error(e);return err('Internal error: '+e.message,500)}},async scheduled(_event,env,ctx){ctx.waitUntil(runDue(env));}};